const body = document.body;

const menu = document.querySelector('.header__wrapper-nav');
const btnOpen = document.querySelector('.burger');
const links = document.querySelectorAll('.nav__link');

function toggleMenu() {
	const isOpen = !menu.classList.contains('active');
	menu.classList.toggle('active');
	btnOpen.classList.toggle('active');
	body.classList.toggle('stop-scroll', isOpen);
}

function closeMenu() {
	menu.classList.remove('active');
	body.classList.remove('stop-scroll');
	btnOpen.classList.remove('active');
}

function clearMenu() {
	const offsetWidth = document.documentElement.offsetWidth;
	if (offsetWidth > 992) {
		closeMenu();
	}
}

btnOpen.addEventListener('click', toggleMenu);
links.forEach(link => {
	link.addEventListener('click', closeMenu);
});

window.addEventListener('resize', clearMenu);